<?php

namespace Tests\Feature;

use App\Services\FpsPlaybookValidator;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;

class FpsPlaybookValidatorTest extends TestCase
{
    use RefreshDatabase;

    private const TOKEN = 'test-writer-token-0123456789abcdef0123';

    /** Generated by the TypeScript playbook (400 simulated rounds, includes learned variants). */
    private function fixture(): array
    {
        return json_decode(file_get_contents(base_path('tests/Fixtures/fps-playbook.json')), true, 512, JSON_THROW_ON_ERROR);
    }

    public function test_evolved_playbook_and_opponent_model_from_the_client_are_accepted(): void
    {
        $validator = new FpsPlaybookValidator();
        $fixture = $this->fixture();
        $this->assertTrue($validator->validPlaybook($fixture['playbook']));
        $this->assertTrue($validator->validOpponents($fixture['opponents']));
        $this->assertNotEmpty(array_filter(array_keys($fixture['playbook']['attack'] + $fixture['playbook']['defense']), fn ($id) => str_starts_with($id, 'v:')), 'fixture contains learned variants');
    }

    public function test_out_of_range_missing_seed_and_unlawful_fields_are_refused(): void
    {
        $validator = new FpsPlaybookValidator();
        $book = $this->fixture()['playbook'];
        $broken = $book; $broken['attack']['seed:rush_a']['spec']['rushBelow'] = 1.4;
        $this->assertFalse($validator->validPlaybook($broken));
        $missing = $book; unset($missing['defense']['seed:standard']);
        $this->assertFalse($validator->validPlaybook($missing));
        $wins = $book; $wins['attack']['seed:rush_b']['wins'] = $wins['attack']['seed:rush_b']['trials'] + 1;
        $this->assertFalse($validator->validPlaybook($wins));
        $opponents = $this->fixture()['opponents'];
        $opponents['opponents']['club:2']['lastPlayId'] = 'seed:rush_b';
        $this->assertFalse($validator->validOpponents($opponents), 'opponent play choices are not lawful information');
    }

    public function test_lineage_accepts_playbook_versions_verbatim(): void
    {
        config(['automatic_learning.writer_token' => self::TOKEN]);
        $bytes = json_encode($this->fixture()['playbook'], JSON_UNESCAPED_SLASHES | JSON_PRESERVE_ZERO_FRACTION);
        $this->withHeaders(['Authorization' => 'Bearer '.self::TOKEN])
            ->postJson('/api/v1/fps/lineages/club:5/versions', ['kind' => 'playbook', 'payload' => $bytes, 'origin' => 'worker', 'promote' => true])
            ->assertCreated();
        $this->assertStringContainsString('"playbook":{"version":1', $this->get('/api/v1/fps/lineages/club:5/current')->getContent());
    }
}
